#!/usr/bin/env python3
import json
import re
import os
import sys

# 1. Parse vocabBuilderData.ts to extract detailed lessons and roots
vocab_builder_path = os.path.join(os.getcwd(), 'src/data/vocabBuilderData.ts')
with open(vocab_builder_path, 'r', encoding='utf-8') as f:
    vocab_data_content = f.read()

# Extract valid roots
root_ids_in_data = set(re.findall(r"id:\s*'(root-[^']+)'", vocab_data_content))
print(f"Found {len(root_ids_in_data)} root IDs in vocabBuilderData.ts: {sorted(list(root_ids_in_data))}")

# Extract lessons
# Parse lesson blocks
lesson_matches = re.findall(r"\{\s*id:\s*'(lesson-\d+)',\s*word:\s*'([^']+)',\s*partOfSpeech:\s*'([^']+)',.*?difficulty:\s*'([^']+)',.*?shortGloss:\s*'([^']+)'", vocab_data_content, re.DOTALL)

preserved_lessons = []
preserved_headwords = set()

for lid, word, pos, diff, gloss in lesson_matches:
    # find rootId if present in etymology
    block_match = re.search(r"id:\s*'" + re.escape(lid) + r"'.*?rootId:\s*'(root-[^']+)'", vocab_data_content, re.DOTALL)
    root_id = block_match.group(1) if block_match else None
    
    # Topic tags inference based on word
    topics = ['Rhetoric & Speech', 'Communication']
    if word.lower() in ['egomaniac', 'ambivert', 'misanthrope', 'altruist']:
        topics = ['Psychology & Personality', 'Behavior']
    elif word.lower() in ['dermatologist', 'neurologist', 'pathologist']:
        topics = ['Medicine & Science', 'Health']
    elif word.lower() in ['pagan', 'cacophony', 'eulogy', 'monologue']:
        topics = ['Language & Culture', 'Rhetoric']
        
    preserved_lessons.append({
        'id': lid,
        'word': word,
        'partOfSpeech': pos,
        'definition': gloss,
        'difficulty': diff,
        'topicTags': topics,
        'rootId': root_id if root_id in root_ids_in_data else None,
        'hasDetailedLesson': True
    })
    preserved_headwords.add(word.strip().lower())

print(f"Extracted {len(preserved_lessons)} preserved detailed lessons.")

# Extract root derived words from vocabBuilderData.ts
root_derived_matches = re.findall(r"derivedWords:\s*\[(.*?)\]", vocab_data_content, re.DOTALL)
root_blocks = re.findall(r"id:\s*'(root-[^']+)',\s*root:\s*'([^']+)',\s*meaning:\s*'([^']+)'", vocab_data_content)

root_map = {}
for rid, rname, rmeaning in root_blocks:
    root_map[rid] = (rname, rmeaning)

# Expand raw derived words
root_word_items = []
derived_sections = re.findall(r"id:\s*'(root-[^']+)'[\s\S]*?derivedWords:\s*\[([\s\S]*?)\]", vocab_data_content)

for rid, derived_str in derived_sections:
    # extract entries like { word: 'Egoist', meaning: '...', pos: 'noun' }
    entries = re.findall(r"word:\s*'([^']+)',\s*meaning:\s*'([^']+)'(?:,\s*pos:\s*'([^']+)')?", derived_str)
    for w, m, pos in entries:
        pos_val = pos if pos else ('noun' if w.endswith('ist') or w.endswith('ity') or w.endswith('ism') else ('adjective' if w.endswith('ic') or w.endswith('ous') or w.endswith('al') else 'noun'))
        w_clean = w.strip()
        if w_clean.lower() not in preserved_headwords:
            root_word_items.append({
                'word': w_clean,
                'partOfSpeech': pos_val,
                'definition': m,
                'difficulty': 'Intermediate',
                'topicTags': ['Etymology', 'Word Families'],
                'rootId': rid if rid in root_ids_in_data else None,
                'hasDetailedLesson': False
            })

print(f"Extracted {len(root_word_items)} root derived words.")

